/* Standards-only Markdown + PNG package, ZIP store method, UTF-8 names. */
(function(root){'use strict';
const enc=new TextEncoder(),bytes=x=>typeof x==='string'?enc.encode(x):x;
function crc32(b){let c=0xffffffff;for(const v of b){c^=v;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0)}return(c^0xffffffff)>>>0}
function zip(files){const chunks=[],central=[];let offset=0;for(const [path,raw]of Object.entries(files)){const name=enc.encode(path),data=bytes(raw),crc=crc32(data),h=new Uint8Array(30+name.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);h.set(name,30);chunks.push(h,data);const c=new Uint8Array(46+name.length),d=new DataView(c.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(8,0x800,true);d.setUint32(16,crc,true);d.setUint32(20,data.length,true);d.setUint32(24,data.length,true);d.setUint16(28,name.length,true);d.setUint32(42,offset,true);c.set(name,46);central.push(c);offset+=h.length+data.length}const size=central.reduce((s,a)=>s+a.length,0),end=new Uint8Array(22),e=new DataView(end.buffer);e.setUint32(0,0x06054b50,true);e.setUint16(8,central.length,true);e.setUint16(10,central.length,true);e.setUint32(12,size,true);e.setUint32(16,offset,true);const all=[...chunks,...central,end],out=new Uint8Array(offset+size+22);let n=0;for(const b of all){out.set(b,n);n+=b.length}return out}
const text=s=>String(s??'未填写').replace(/</g,'&lt;').replace(/>/g,'&gt;'),cell=s=>text(s).replace(/\|/g,'\\|').replace(/[\r\n]+/g,' ');
function markdown({meta,data,workbench,design},assets=[]){const steps=design.experiment?.steps||[];let s='# '+text(meta.title||'实验日志')+'\n\n日期：'+text(meta.date)+' · 记录人：'+text(meta.author)+'\n\n## 1. 实验目的与设置\n\n'+text(meta.purpose)+'\n\n'+text(meta.settings)+'\n\n## 2. 当前模拟光路\n\n'+(assets.includes('optical-layout.png')?'![模拟光路](assets/optical-layout.png)':'未提供光路图片。')+'\n\n## 3. 预设动作\n\n仅记录模拟器流程，不代表 LabVIEW 或真实硬件执行。\n\n'+(steps.length?steps.map((step,i)=>(i+1)+'. '+text(root.LabLogCore.describeStep(step,design))).join('\n'):'尚未录制动作。')+'\n\n## 4. 导入数据与曲线\n\n'+(data?'来源：'+text(data.filename)+'；数据性质：'+text(data.kind)+'\n\n[编辑后数据 TSV](assets/data.tsv)':'尚未导入数据。')+'\n\n';for(const a of assets.filter(x=>x!=='optical-layout.png'))s+='!['+(a==='polar-plot.png'?'Polar plot':'数据曲线')+'](assets/'+a+')\n\n';if(workbench?.fitResult){const f=workbench.fitResult;s+='拟合公式：'+text(f.equation||workbench.config?.expression)+'\n\n'+Object.entries(f.params||{}).map(([k,v])=>'- '+text(k)+' = '+v).join('\n')+'\n\nR²：'+f.r2+'；RMSE：'+(f.RMSE??f.rmse)+'；数值收敛：'+(f.converged?'是':'否')+'\n\n'}return s}
function fromDataURL(s){return Uint8Array.from(atob(s.split(',')[1]),c=>c.charCodeAt(0))}
async function png(svg){if(!svg.startsWith('<svg'))throw Error('曲线无法导出为图片，请检查数据（极坐标半径不能为负）');const u=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('曲线图片生成失败'));image.src=u});const c=document.createElement('canvas');c.width=1520;c.height=840;const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(image,0,0,c.width,c.height);return fromDataURL(c.toDataURL('image/png'))}finally{URL.revokeObjectURL(u)}}
async function files(args){const files={},assets=[],prefix='experiment/';if(args.image&&/^data:image\/png;base64,/.test(args.image)){files[prefix+'assets/optical-layout.png']=fromDataURL(args.image);assets.push('optical-layout.png')}if(args.data){files[prefix+'assets/data.tsv']=args.data.raw;const pts=root.LabLogCore.map(root.LabLogCore.parse(args.data.raw,args.data.parser),args.data.mapping).points,cfg={...(args.workbench?.config||{}),xLabel:args.data.mapping.xLabel,yLabel:args.data.mapping.yLabel};if(pts.length){files[prefix+'assets/data-plot.png']=await png(root.DataWorkbenchCore.plot(pts,cfg,args.workbench?.fitResult));assets.push('data-plot.png');if(cfg.showPolar&&cfg.kind!=='polar'){files[prefix+'assets/polar-plot.png']=await png(root.DataWorkbenchCore.plot(pts,{...cfg,kind:'polar'},args.workbench?.fitResult));assets.push('polar-plot.png')}}}if(args.workbench){files[prefix+'assets/analysis.json']=JSON.stringify(args.workbench,null,2);if(args.workbench.source?.raw)files[prefix+'assets/original-data.txt']=args.workbench.source.raw;}files[prefix+'assets/design.json']=JSON.stringify(args.design,null,2);files[prefix+'experiment.md']=markdown(args,assets);return files}
function notionOnly(all){const out={};for(const [path,data]of Object.entries(all)){if(path.endsWith('/experiment.md'))out['experiment.md']=data.replace(/\[编辑后数据 TSV\]\(assets\/data.tsv\)/g,'原始数据与编辑后数据另存于本地归档。').replace(/\[完整设计 JSON\]\(assets\/design.json\)/g,'完整设计另存于本地归档。').replace(/\]\(assets\//g,'](');else if(path.endsWith('.png'))out[path.split('/').pop()]=data}return out}
function combine(packs,title='全部实验记录'){const out={},chapters=[];packs.forEach((pack,i)=>{const clean=notionOnly(pack);let md=clean['experiment.md']||'';for(const [name,data]of Object.entries(clean)){if(!name.endsWith('.png'))continue;const target='sheet-'+(i+1)+'-'+name;out[target]=data;md=md.split(']('+name+')').join(']('+target+')')}md=md.replace(/^(#{1,5}) /gm,'$1# ');chapters.push(md)});out['experiment.md']='# '+title+'\n\n共 '+packs.length+' 个实验；按 Sheet 顺序排列。\n\n'+chapters.join('\n\n---\n\n');return out}
async function build(args){return zip(notionOnly(await files(args)))}
async function download(args){const data=await build(args),u=URL.createObjectURL(new Blob([data],{type:'application/zip'})),a=document.createElement('a');a.href=u;a.download='experiment-notion.zip';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
root.NotionExport={zip,markdown,files,notionOnly,combine,build,download};if(typeof module!=='undefined')module.exports=root.NotionExport;
})(typeof window!=='undefined'?window:globalThis);
